// Parse and validate analytics event
const input = $input.first().json;
const body = input.body || input;

if (!body.event && !body.type) {
  throw new Error('Missing required field: event or type');
}

const event = {
  id: `evt_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  type: body.event || body.type,
  category: body.category || 'general',
  value: body.value || 1,
  dimensions: body.dimensions || {},
  metadata: body.metadata || {},
  timestamp: new Date().toISOString(),
  epochMs: Date.now()
};

return [{ json: event }];

// Real-time aggregation (last 5 minutes)
const event = $input.first().json;
const staticData = $workflow.staticData;
const now = Date.now();
const windowMs = 5 * 60 * 1000; // 5 minutes

// Initialize aggregation buckets
if (!staticData.realtime) {
  staticData.realtime = {
    events: [],
    counts: {},
    sums: {},
    lastCleanup: now
  };
}

const rt = staticData.realtime;

// Cleanup old events (every minute)
if (now - rt.lastCleanup > 60000) {
  rt.events = rt.events.filter(e => now - e.epochMs < windowMs);
  rt.lastCleanup = now;
}

// Add current event
rt.events.push(event);

// Update counts
const key = `${event.category}:${event.type}`;
rt.counts[key] = (rt.counts[key] || 0) + 1;
rt.sums[key] = (rt.sums[key] || 0) + event.value;

// Calculate real-time metrics
const recentEvents = rt.events.filter(e => now - e.epochMs < windowMs);
const metrics = {
  window: '5m',
  eventCount: recentEvents.length,
  eventsPerMinute: (recentEvents.length / 5).toFixed(2),
  byCategory: {},
  byType: {}
};

// Aggregate by category and type
for (const e of recentEvents) {
  metrics.byCategory[e.category] = (metrics.byCategory[e.category] || 0) + 1;
  metrics.byType[e.type] = (metrics.byType[e.type] || 0) + 1;
}

return [{
  json: {
    event,
    realtime: metrics
  }
}];

// Hourly roll-up aggregation
const data = $input.first().json;
const staticData = $workflow.staticData;
const now = new Date();
const hourKey = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}-${String(now.getHours()).padStart(2, '0')}`;

// Initialize hourly buckets
if (!staticData.hourly) {
  staticData.hourly = {};
}

if (!staticData.hourly[hourKey]) {
  staticData.hourly[hourKey] = {
    hour: hourKey,
    startTime: new Date(now.getFullYear(), now.getMonth(), now.getDate(), now.getHours()).toISOString(),
    counts: {},
    sums: {},
    uniqueUsers: new Set(),
    eventCount: 0
  };
}

const bucket = staticData.hourly[hourKey];
bucket.eventCount++;

const key = `${data.event.category}:${data.event.type}`;
bucket.counts[key] = (bucket.counts[key] || 0) + 1;
bucket.sums[key] = (bucket.sums[key] || 0) + data.event.value;

if (data.event.dimensions?.userId) {
  bucket.uniqueUsers.add(data.event.dimensions.userId);
}

// Clean up old hours (keep last 24)
const hours = Object.keys(staticData.hourly).sort();
if (hours.length > 24) {
  for (const oldHour of hours.slice(0, -24)) {
    delete staticData.hourly[oldHour];
  }
}

return [{
  json: {
    ...data,
    hourly: {
      bucket: hourKey,
      eventCount: bucket.eventCount,
      uniqueUsers: bucket.uniqueUsers.size || 0
    }
  }
}];

// Daily roll-up aggregation
const data = $input.first().json;
const staticData = $workflow.staticData;
const now = new Date();
const dayKey = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;

// Initialize daily buckets
if (!staticData.daily) {
  staticData.daily = {};
}

if (!staticData.daily[dayKey]) {
  staticData.daily[dayKey] = {
    date: dayKey,
    counts: {},
    sums: {},
    uniqueUsers: new Set(),
    eventCount: 0,
    peakHour: null,
    peakHourCount: 0
  };
}

const bucket = staticData.daily[dayKey];
bucket.eventCount++;

const key = `${data.event.category}:${data.event.type}`;
bucket.counts[key] = (bucket.counts[key] || 0) + 1;
bucket.sums[key] = (bucket.sums[key] || 0) + data.event.value;

// Track peak hour
const currentHour = now.getHours();
if (!bucket.hourlyBreakdown) bucket.hourlyBreakdown = {};
bucket.hourlyBreakdown[currentHour] = (bucket.hourlyBreakdown[currentHour] || 0) + 1;

if (bucket.hourlyBreakdown[currentHour] > bucket.peakHourCount) {
  bucket.peakHourCount = bucket.hourlyBreakdown[currentHour];
  bucket.peakHour = currentHour;
}

// Clean up old days (keep last 30)
const days = Object.keys(staticData.daily).sort();
if (days.length > 30) {
  for (const oldDay of days.slice(0, -30)) {
    delete staticData.daily[oldDay];
  }
}

return [{
  json: {
    ...data,
    daily: {
      date: dayKey,
      eventCount: bucket.eventCount,
      peakHour: bucket.peakHour
    }
  }
}];

// Anomaly detection using statistical methods
const data = $input.first().json;
const staticData = $workflow.staticData;

// Initialize anomaly detection state
if (!staticData.anomalyDetection) {
  staticData.anomalyDetection = {
    history: [],
    mean: 0,
    stdDev: 0,
    threshold: 2 // 2 standard deviations
  };
}

const ad = staticData.anomalyDetection;
const currentRate = parseFloat(data.realtime.eventsPerMinute);

// Add to history (keep last 100 data points)
ad.history.push(currentRate);
if (ad.history.length > 100) {
  ad.history.shift();
}

// Calculate mean and standard deviation
const n = ad.history.length;
if (n >= 10) {
  ad.mean = ad.history.reduce((a, b) => a + b, 0) / n;
  const variance = ad.history.reduce((acc, val) => acc + Math.pow(val - ad.mean, 2), 0) / n;
  ad.stdDev = Math.sqrt(variance);
}

// Detect anomaly
const anomalies = [];
if (n >= 10 && ad.stdDev > 0) {
  const zScore = Math.abs((currentRate - ad.mean) / ad.stdDev);

  if (zScore > ad.threshold) {
    anomalies.push({
      type: currentRate > ad.mean ? 'spike' : 'drop',
      metric: 'events_per_minute',
      currentValue: currentRate,
      expectedValue: ad.mean.toFixed(2),
      deviation: zScore.toFixed(2),
      severity: zScore > 3 ? 'critical' : 'warning'
    });
  }
}

return [{
  json: {
    ...data,
    anomalyDetection: {
      enabled: true,
      dataPoints: n,
      mean: ad.mean.toFixed(2),
      stdDev: ad.stdDev.toFixed(2),
      anomaliesDetected: anomalies.length > 0,
      anomalies
    }
  }
}];

// Generate anomaly alert
const data = $input.first().json;

const alert = {
  type: 'ANALYTICS_ANOMALY',
  priority: data.anomalyDetection.anomalies[0]?.severity === 'critical' ? 'P1' : 'P2',
  alertId: `alert_${Date.now()}`,
  anomalies: data.anomalyDetection.anomalies,
  context: {
    eventType: data.event.type,
    category: data.event.category,
    realtimeMetrics: data.realtime
  },
  createdAt: new Date().toISOString()
};

console.log('ANOMALY ALERT:', JSON.stringify(alert, null, 2));

return [{ json: { ...data, alert } }];

// Format response with dashboard data
const data = $input.first().json;

const response = {
  success: true,
  eventId: data.event.id,
  eventType: data.event.type,

  metrics: {
    realtime: data.realtime,
    hourly: data.hourly,
    daily: data.daily
  },

  anomalyDetection: {
    status: data.anomalyDetection.enabled ? 'active' : 'inactive',
    anomaliesDetected: data.anomalyDetection.anomaliesDetected,
    anomalies: data.anomalyDetection.anomalies || []
  },

  alert: data.alert || null,

  processedAt: new Date().toISOString()
};

return [{ json: response }];

// Generate dashboard data
const staticData = $workflow.staticData;
const query = $input.first().json.query || {};

const dashboard = {
  generatedAt: new Date().toISOString(),

  realtime: {
    window: '5m',
    eventCount: staticData.realtime?.events?.length || 0,
    eventsPerMinute: staticData.realtime?.events ? 
      ((staticData.realtime.events.filter(e => Date.now() - e.epochMs < 300000).length) / 5).toFixed(2) : 0
  },

  hourly: Object.values(staticData.hourly || {})
    .sort((a, b) => b.hour.localeCompare(a.hour))
    .slice(0, 24)
    .map(h => ({
      hour: h.hour,
      eventCount: h.eventCount,
      uniqueUsers: h.uniqueUsers?.size || 0
    })),

  daily: Object.values(staticData.daily || {})
    .sort((a, b) => b.date.localeCompare(a.date))
    .slice(0, 7)
    .map(d => ({
      date: d.date,
      eventCount: d.eventCount,
      peakHour: d.peakHour
    })),

  anomalyDetection: {
    mean: staticData.anomalyDetection?.mean?.toFixed(2) || 'N/A',
    stdDev: staticData.anomalyDetection?.stdDev?.toFixed(2) || 'N/A',
    dataPoints: staticData.anomalyDetection?.history?.length || 0
  }
};

return [{ json: dashboard }];
